-- EraLens period import: yuan-ming-qing
-- Window: 1206-01 .. 1912-02
BEGIN;

-- cleanup
DELETE FROM events WHERE id = 'lu-jian-enthroned';
DELETE FROM events WHERE id = 'yuan-north-end';
DELETE FROM reigns WHERE dynasty_id = 'yuan-north';
DELETE FROM dynasties WHERE id = 'yuan-north';
-- remove stale auto-generated 史料缺 (两都之战并行叠放、驾崩至即位短空档应留白)
DELETE FROM reigns WHERE dynasty_id IN ('yuan') AND person_id = 'system-missing-ruler';
DELETE FROM relations WHERE id IN ('rel-yeshuntuemur-ragibagh-succession', 'rel-ragibagh-tugh-temur-succession', 'rel-khoshila-irinchibal-succession');
DELETE FROM reigns WHERE id = 'reign-puyi-qing-forbidden';
DELETE FROM events WHERE id = 'qing-moves-capital-to-beijing';
DELETE FROM events WHERE id = 'shaowu-enthroned';

-- persons
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('temur', '铁穆耳', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '铁穆耳，元成宗，忽必烈之孙。即位后确认忽必烈以来的制度与对外和议，暂停大规模征战，并处理西北诸王与元廷的冲突；在位后期健康恶化且未明确继承人，死后发生皇位继承争议。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/元成宗"}]'::jsonb, '钦明广孝皇帝', '成宗', '元成宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('khayishan', '海山', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '海山，元武宗，长期在北方统兵，元成宗去世后在军队与蒙古宗王支持下即位。他以封赏和扩张官僚体系巩固新政权，并与弟爱育黎拔力八达约定兄终弟及；其朝财政开支扩大，纸币贬值加剧。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/元武宗"}]'::jsonb, '仁惠宣孝皇帝', '武宗', '元武宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('ayurbarwada', '爱育黎拔力八达', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '爱育黎拔力八达，元仁宗，元武宗之弟，依兄弟间的继承约定即位。其朝恢复科举取士，重用儒臣并调整财政与官制，推动元廷采用较多中原文官制度；身后由子硕德八剌继位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/元仁宗"}]'::jsonb, '圣文钦孝皇帝', '仁宗', '元仁宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
