VALUES ('yeshuntuemur', '也孙铁木儿', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '也孙铁木儿，元泰定帝，元武宗之侄，在大都与上都政治势力支持下即位。其朝以稳固蒙古宗王与勋贵为要务；1328年去世后，权臣拥立其子阿速吉八，随即引发两都之战。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/元泰定帝"}]'::jsonb, NULL, NULL, '元泰定帝')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('ragibagh', '阿速吉八', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '阿速吉八，元天顺帝，也孙铁木儿之子。泰定帝去世后，他在上都由权臣倒剌沙拥立；同年，支持图帖睦尔的势力在大都发动政变并赢得两都之战，阿速吉八败亡，在位仅数周。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/阿速吉八"}]'::jsonb, NULL, NULL, '元天顺帝')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('tugh-temur', '图帖睦尔', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '图帖睦尔，元文宗，元武宗之子。两都之战中获胜后即位，曾让位于兄长和世㻋；和世㻋去世后复位。其朝设奎章阁、召集文臣编修典籍，皇位反复更替与权臣斗争仍持续。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/元文宗"}]'::jsonb, '圣明元孝皇帝', '文宗', '元文宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('khoshila', '和世㻋', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '和世㻋，元明宗，元武宗长子，曾长期流寓漠北。1328年在上都即位，次年与弟图帖睦尔会合并恢复兄弟继位安排；不久在赴大都途中去世，史籍记其死于宴会之后，死因说法不一。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/和世㻋"}]'::jsonb, '翼献景孝皇帝', '明宗', '元明宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('irinchibal', '懿璘质班', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '懿璘质班，元宁宗，元明宗幼子。1332年由权臣拥立时年仅七岁，在位约两个月便病逝；随后元廷迎立其异母兄妥懽帖睦尔。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/元宁宗"}]'::jsonb, '冲圣嗣孝皇帝', '宁宗', '元宁宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('togon-temur', '妥懽帖睦尔', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '妥懽帖睦尔，元顺帝，元朝在中原的末代皇帝。其长期在位期间朝廷屡受权臣与派系斗争影响，黄河水患、财政危机及红巾军起义相继爆发；1368年明军攻入大都，他北走上都，元廷退居漠北。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/元顺帝"}]'::jsonb, '顺帝', '惠宗', '元惠宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('xu-shouhui', '徐寿辉', ARRAY[]::text[], NULL, NULL, 1320, 1, NULL, 'year', 1360, 1, NULL, 'year', ARRAY['皇帝'], '罗田人，元末红巾军首领。1351年在蕲水起事称帝，以蕲水为都，后迁汉阳；部众一度扩展至湖广、江西等地，政权称宋，史籍亦称天完。陈友谅掌握军政后挟其东下，1360年在采石被杀。明玉珍后来追谥应天启运献武皇帝、庙号世宗。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/徐寿辉"}]'::jsonb, '应天启运献武皇帝', '世宗', '徐宋世宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('chen-youliang', '陈友谅', ARRAY[]::text[], NULL, NULL, 1320, 1, NULL, 'year', 1363, 1, NULL, 'year', ARRAY['皇帝'], '原为徐寿辉部将，后兼并倪文俊余部并控制江西、湖广多地。1359年自称汉王，次年在采石杀徐寿辉后称帝、国号汉，定都江州，后迁武昌。与朱元璋争夺长江中下游，1363年鄱阳湖之战兵败，中流矢身亡。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/陈友谅"}]'::jsonb, NULL, NULL, '陈汉帝')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('chen-li', '陈理', ARRAY[]::text[], NULL, NULL, 1351, 1, NULL, 'year', 1408, 1, NULL, 'year', ARRAY['皇帝'], '陈友谅次子。父亲在鄱阳湖战死后于武昌继位，改元德寿；朱元璋次年亲征，陈理出降，陈汉政权告终，后被封归德侯。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/陈理_(元末)"}]'::jsonb, NULL, NULL, '陈汉帝')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('han-liner', '韩林儿', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, 1366, 1, NULL, 'year', ARRAY['皇帝'], '韩山童之子，红巾军拥立的宋政权君主，号小明王。1355年刘福通等在亳州奉其称帝，年号龙凤；韩宋势力曾据汴梁，失守后退守安丰。刘福通战死后，他投奔朱元璋，1366年渡江途中溺亡，政权随之终结。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩林儿"}]'::jsonb, NULL, NULL, '小明王')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
