VALUES ('ming-sheng', '明升', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, 1371, 1, NULL, 'year', ARRAY['皇帝'], '明玉珍之子，父死后于1366年继位为夏主。1371年明军攻入重庆，明升出降，明夏亡；后被迁往高丽。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/明升"}]'::jsonb, NULL, NULL, '明夏帝')
