VALUES ('liu-futong', '刘福通', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, 1363, 1, NULL, 'year', ARRAY['起义领袖'], '红巾军首领，拥立韩林儿为小明王，三路北伐；1363年安丰之战战死。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘福通"}]'::jsonb, NULL, NULL, NULL)
