VALUES ('zhu-yousong', '朱由崧', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '弘光帝，南明首任，都南京，被俘处死。在南明（1644年—1645年）在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/弘光帝"}]'::jsonb, NULL, NULL, '弘光帝')
