VALUES ('zhu-yuyue', '朱聿鐭', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '绍武帝，隆武之弟，1646年广州称帝，与肇庆永历并立，旋为清军所破。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/绍武帝"}]'::jsonb, NULL, NULL, '绍武帝')
