VALUES ('liu-ji', '刘基', ARRAY[]::text[], NULL, NULL, 1311, 1, NULL, 'year', 1375, 1, NULL, 'year', ARRAY['政治家','军事家'], '明初政治家、文学家，字伯温，浙江青田人。元末出仕后归附朱元璋，参与谋划统一战争及建国制度；洪武年间封诚意伯，著有《郁离子》及诗文集。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘基"}]'::jsonb, NULL, NULL, NULL)
