VALUES ('lan-yu', '蓝玉', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, 1393, 1, NULL, 'year', ARRAY['军事家'], '明初大将，捕鱼儿海大破北元，后涉党案被诛；洪武二十一年捕鱼儿海战俘获北元皇子与大量军民，后因蓝玉案被杀并株连多人。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/蓝玉"}]'::jsonb, NULL, NULL, NULL)
