VALUES ('zhang-juzheng', '张居正', ARRAY[]::text[], NULL, NULL, 1525, 1, NULL, 'year', 1582, 1, NULL, 'year', ARRAY['政治家'], '明神宗首辅，推行考成法、一条鞭法等改革，史称万历中兴；万历初推行考成法、清丈土地与一条鞭法；死后被夺谥籍产，天启年间复名。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张居正"}]'::jsonb, NULL, NULL, NULL)
