VALUES ('hai-rui', '海瑞', ARRAY[]::text[], NULL, NULL, 1514, 1, NULL, 'year', 1587, 1, NULL, 'year', ARRAY['政治家'], '明代官员，字汝贤，号刚峰，琼山人。嘉靖年间任职地方，因上《治安疏》直谏世宗而下狱；后历任地方官，推行清丈、整饬吏治，以刚直敢言著称。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/海瑞"}]'::jsonb, NULL, NULL, NULL)
