VALUES ('qi-jiguang', '戚继光', ARRAY[]::text[], NULL, NULL, 1528, 1, NULL, 'year', 1588, 1, NULL, 'year', ARRAY['军事家'], '明代抗倭名将，组建戚家军，平定东南倭患；在浙江、福建训练戚家军抗倭，后转守蓟州；著有《纪效新书》《练兵实纪》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/戚继光"}]'::jsonb, NULL, NULL, NULL)
