VALUES ('xu-xiake', '徐霞客', ARRAY[]::text[], NULL, NULL, 1587, 1, NULL, 'year', 1641, 1, NULL, 'year', ARRAY['地理学家'], '明代地理学家、旅行家，名弘祖，字振之，南直隶江阴人。自青年起多次远游，考察山川、洞穴与水系，行旅日记由后人整理为《徐霞客游记》，兼具地理观察与文学价值。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/徐霞客"}]'::jsonb, NULL, NULL, NULL)
