VALUES ('wei-zhongxian', '魏忠贤', ARRAY[]::text[], NULL, NULL, 1568, 1, NULL, 'year', 1627, 1, NULL, 'year', ARRAY['政治家'], '明末权阉，天启朝专权，东林党争对手，后自缢；他控制东厂并打击东林党人，崇祯即位后失势，在逮捕途中自缢。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏忠贤"}]'::jsonb, NULL, NULL, NULL)
