VALUES ('zheng-he', '郑和', ARRAY[]::text[], NULL, NULL, 1371, 1, NULL, 'year', 1433, 1, NULL, 'year', ARRAY['军事家'], '明代航海家，永乐朝率船队七下西洋，沟通中外；船队七下西洋，开展外交、贸易往来，航迹抵达印度洋与东非沿岸。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑和"}]'::jsonb, NULL, NULL, NULL)
