VALUES ('dorgon', '多尔衮', ARRAY[]::text[], NULL, NULL, 1612, 1, NULL, 'year', 1650, 1, NULL, 'year', ARRAY['政治家','军事家'], '清初满洲贵族，爱新觉罗氏，努尔哈赤第十四子。皇太极死后拥立顺治帝并摄政，统兵入关、迁都北京，主导清初统一与制度建设；死后曾被追尊，后遭削爵，乾隆朝复爵。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/多尔衮"}]'::jsonb, NULL, NULL, NULL)
