VALUES ('huang-zongxi', '黄宗羲', ARRAY[]::text[], NULL, NULL, 1610, 1, NULL, 'year', 1695, 1, NULL, 'year', ARRAY['思想家'], '明末清初思想家，明夷待访录作者，批判君主专制；《明夷待访录》提出限制君权、学校议政等主张，后世常视为早期政治批判著作。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/黄宗羲"}]'::jsonb, NULL, NULL, NULL)
