VALUES ('gu-yanwu', '顾炎武', ARRAY[]::text[], NULL, NULL, 1613, 1, NULL, 'year', 1682, 1, NULL, 'year', ARRAY['思想家'], '明末清初思想家，日知录作者，经世致用代表；长期游历并搜集碑刻、地理资料；《日知录》《天下郡国利病书》体现经世关怀。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/顾炎武"}]'::jsonb, NULL, NULL, NULL)
