VALUES ('cao-xueqin', '曹雪芹', ARRAY[]::text[], NULL, NULL, 1715, 1, NULL, 'year', 1763, 1, NULL, 'year', ARRAY['文学家'], '清代小说家，名霑，字梦阮，号雪芹，出身江宁织造曹氏家族。家道衰落后居北京西郊，晚年创作《红楼梦》；生卒年与小说定稿情况均有不同考说。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹雪芹"}]'::jsonb, NULL, NULL, NULL)
