VALUES ('ji-xiaolan', '纪晓岚', ARRAY[]::text[], NULL, NULL, 1724, 1, NULL, 'year', 1805, 1, NULL, 'year', ARRAY['文学家','政治家'], '清代学者，四库全书总纂官，阅微草堂笔记作者；奉命主持《四库全书》编纂，另著笔记小说《阅微草堂笔记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/纪晓岚"}]'::jsonb, NULL, NULL, NULL)
