VALUES ('zeng-guofan', '曾国藩', ARRAY[]::text[], NULL, NULL, 1811, 1, NULL, 'year', 1872, 1, NULL, 'year', ARRAY['政治家','军事家'], '晚清政治家、军事统帅，初名子城，字伯涵，湖南湘乡人。奉命在湖南编练湘军，镇压太平天国；历任两江总督等职，推动洋务事业，家书与文集广泛流传。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曾国藩"}]'::jsonb, NULL, NULL, NULL)
