VALUES ('li-hongzhang', '李鸿章', ARRAY[]::text[], NULL, NULL, 1823, 1, NULL, 'year', 1901, 1, NULL, 'year', ARRAY['政治家','军事家'], '晚清政治家、外交家，字少荃，安徽合肥人。创办淮军并参与洋务运动，任直隶总督、北洋大臣；代表清政府办理多项外交事务并签订《马关条约》《辛丑条约》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李鸿章"}]'::jsonb, NULL, NULL, NULL)
