VALUES ('zuo-zongtang', '左宗棠', ARRAY[]::text[], NULL, NULL, 1812, 1, NULL, 'year', 1885, 1, NULL, 'year', ARRAY['政治家','军事家'], '晚清政治家、军事统帅，字季高，湖南湘阴人。曾参与镇压太平天国与捻军，任陕甘总督后率军收复新疆；倡办福州船政局等洋务事业，晚年任军机大臣。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/左宗棠"}]'::jsonb, NULL, NULL, NULL)
