VALUES ('deng-shichang', '邓世昌', ARRAY[]::text[], NULL, NULL, 1849, 1, NULL, 'year', 1894, 1, NULL, 'year', ARRAY['军事家'], '清末海军将领，字正卿，广东番禺人，出身水师学堂。任致远舰管带，甲午战争黄海海战中率舰作战，舰沉后与官兵一同殉难；其事迹成为近代海军史的重要记忆。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/邓世昌"}]'::jsonb, NULL, NULL, NULL)
