VALUES ('liang-qichao', '梁启超', ARRAY[]::text[], NULL, NULL, 1873, 1, NULL, 'year', 1929, 1, NULL, 'year', ARRAY['政治家','思想家'], '晚清思想家、政治家、新闻人，字卓如，号任公，广东新会人。师从康有为并参与戊戌变法，流亡期间创办报刊、倡导立宪与新民思想；回国后转向学术研究，著述丰富。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/梁启超"}]'::jsonb, NULL, NULL, NULL)
