VALUES ('tan-sitong', '谭嗣同', ARRAY[]::text[], NULL, NULL, 1865, 1, NULL, 'year', 1898, 1, NULL, 'year', ARRAY['政治家','思想家'], '戊戌维新人物，变法失败后遇害，列为戊戌六君子；变法失败后拒绝出逃，1898年在北京遇害；《仁学》批判旧制度与纲常。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/谭嗣同"}]'::jsonb, NULL, NULL, NULL)
