VALUES ('nurhaci', '努尔哈赤', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '爱新觉罗·努尔哈赤，建州女真首领，清太祖。1616年建立后金，统一女真各部并创建八旗；对明战争中于宁远失利，1626年病逝。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/努尔哈赤"}]'::jsonb, '武皇帝', '太祖', '清太祖')
