VALUES ('huang-taiji', '皇太极', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '爱新觉罗·皇太极，努尔哈赤第八子，清太宗。1626年继承汗位，改革政制、整编八旗；1636年改国号为大清并称帝，为清军入关奠定基础。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/皇太极"},{"label":"《清史稿·朝鲜列传》：天聪十年改元崇德、国号大清","url":"https://db.history.go.kr/item/compareViewer.do?levelId=jo_024_0010_0020_0130"}]'::jsonb, '文皇帝', '太宗', '清太宗')
