VALUES ('fulin', '福临', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '爱新觉罗·福临，皇太极第九子，清世祖。幼年即位，由多尔衮摄政；1644年清军入关并迁都北京，顺治亲政后整顿政务，确立清朝对中原的统治。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/顺治帝"}]'::jsonb, '章皇帝', '世祖', '清世祖')
