VALUES ('xuanye', '玄烨', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '爱新觉罗·玄烨，顺治帝第三子，清圣祖。亲政后平定三藩、统一台湾，抗击准噶尔并签订《尼布楚条约》，康熙朝国势与疆域进一步发展。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/康熙帝"}]'::jsonb, '仁皇帝', '圣祖', '清圣祖')
