VALUES ('yinzhen', '胤禛', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '爱新觉罗·胤禛，康熙帝第四子，清世宗。即位后整顿财政，推行摊丁入亩、耗羡归公等政策，实行改土归流并设军机处，加强中央集权。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/雍正帝"}]'::jsonb, '宪皇帝', '世宗', '清世宗')
