VALUES ('minning', '旻宁', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '爱新觉罗·旻宁，嘉庆帝次子，清宣宗。道光朝面对鸦片输入与边疆、财政问题，1839年命林则徐禁烟；鸦片战争失败后签订《南京条约》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/道光帝"}]'::jsonb, '成皇帝', '宣宗', '清宣宗')
