VALUES ('yizhu', '奕詝', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '爱新觉罗·奕詝，道光帝第四子，清文宗。咸丰朝爆发太平天国运动，清廷又在第二次鸦片战争中战败；英法联军攻入北京后，他避居热河并于1861年病逝。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/咸丰帝"}]'::jsonb, '显皇帝', '文宗', '清文宗')
