VALUES ('ci-xi', '慈禧', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇太后','政治家'], '叶赫那拉氏，咸丰帝妃、同治帝生母，与恭亲王奕訢发动辛酉政变并开始垂帘听政。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慈禧"}]'::jsonb, NULL, NULL, NULL)
