VALUES ('ci-an', '慈安', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇太后','政治家'], '钮祜禄氏，咸丰帝皇后；辛酉政变后与慈禧共同垂帘听政；政变后与慈禧共同辅佐同治、光绪两朝；史料对她去世原因有不同解释。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慈安"}]'::jsonb, NULL, NULL, NULL)
