VALUES ('zaitian', '载湉', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '爱新觉罗·载湉，醇亲王奕譞之子，清德宗。亲政后支持康有为等推行戊戌变法；庚子事变后清廷推进新政，1908年病逝。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/光绪帝"}]'::jsonb, '景皇帝', '德宗', '清德宗')
