VALUES ('sun-yat-sen', '孙中山', ARRAY[]::text[], NULL, NULL, 1866, 1, NULL, 'year', 1925, 1, NULL, 'year', ARRAY['政治家'], '孙中山是近代革命运动的重要领袖，参与组织兴中会、同盟会并推动反清革命。武昌起义后各省代表推举他为中华民国临时大总统，1912年在南京就职；清帝退位后，他依约让位于袁世凯，转而致力于改组政党与推动革命。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孙中山"}]'::jsonb, NULL, NULL, '临时大总统')
