VALUES ('yuan', '{"periods":[{"name":"蒙古帝国","start":{"year":1206,"month":1,"confidence":"year"},"end":{"year":1271,"month":12,"day":18,"confidence":"day"}},{"name":"元","start":{"year":1271,"month":12,"day":18,"confidence":"day"},"end":{"year":1388,"month":11,"confidence":"month"}}]}', ARRAY['元','大元','蒙元','北元','残元','故元','蒙古帝国','大蒙古国','蒙古汗国'], '蒙古', 'cn', 'east_asia', 1206, 1, NULL, 'year', 1388, 11, NULL, 'month', 14472, 16666, 'ochre', NULL, NULL, '1206年铁木真称成吉思汗建国；1271年忽必烈定国号大元，中原史语境转入元朝。帝国诸汗国此后分治。
忽必烈1271年定国号大元；1368年顺帝北逃漠北继续称大元。北元延续至1388年11月天元帝被杀，政权终结。')
