VALUES ('song-xu', '徐宋', ARRAY['宋','天完'], NULL, 'cn', 'east_asia', 1351, 10, NULL, 'year', 1360, 6, NULL, 'month', 16221, 16325, 'ochre', NULL, NULL, '元末红巾军建立的区域政权。徐寿辉1351年在蕲水称帝，后迁都汉阳，势力一度扩展至湖广、江西；国号及政权称谓在史籍中有宋、天完等不同记载。陈友谅掌权并于1360年杀徐寿辉，徐宋由此终结。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ethnicity = EXCLUDED.ethnicity, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, start_confidence = EXCLUDED.start_confidence, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, end_confidence = EXCLUDED.end_confidence, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
