VALUES ('zhou-zhang', '大周', ARRAY['大周','周'], NULL, 'cn', 'east_asia', 1354, 1, NULL, 'year', 1367, 9, NULL, 'month', 16248, 16412, 'ochre', NULL, NULL, '张士诚起兵后于1354年在高邮称诚王、国号周，建元天祐，1356年据平江并以江南为根基。1363年改称吴王；朱元璋军围攻平江，城破后张士诚被俘，政权于1367年覆亡。')
