VALUES ('chen-han', '陈汉', ARRAY['汉','大汉'], NULL, 'cn', 'east_asia', 1360, 6, NULL, 'year', 1364, 1, NULL, 'year', 16325, 16368, 'ochre', NULL, NULL, '陈友谅由徐寿辉部将崛起，控制湖广、江西等地，1360年杀徐寿辉后称帝、国号汉。政权以江州、武昌为中心，与朱元璋争夺长江流域；1363年鄱阳湖战败，陈友谅阵亡，子陈理继位，次年出降，陈汉亡。')
