INSERT INTO dynasties (id, name, alt_names, ethnicity, scope, region, start_year, start_month, start_day, start_confidence, end_year, end_month, end_day, end_confidence, start_abs, end_abs, color_token, parent_id, group_id, note)
VALUES ('ming', '{"periods":[{"name":"吴","start":{"year":1364,"month":2,"day":4,"confidence":"day"},"end":{"year":1368,"month":1,"day":23,"confidence":"day"}},{"name":"明","start":{"year":1368,"month":1,"day":23,"confidence":"day"},"end":{"year":1644,"month":4,"day":25,"confidence":"day"}},{"name":"南明","start":{"year":1644,"month":6,"day":19,"confidence":"day"},"end":{"year":1662,"month":6,"day":1,"confidence":"day"}}]}', ARRAY['明','大明','吴','西吴','南明'], NULL, 'cn', 'east_asia', 1364, 1, NULL, 'year', 1662, 12, NULL, 'year', 16368, 19955, 'ochre', NULL, NULL, '朱元璋以应天为中心经营江南，击败陈友谅、张士诚后，于1364年称吴王，起初仍奉韩宋龙凤年号。1367年改用吴年号并发动北伐；次年在应天称帝、建立明朝，吴政权阶段结束。
朱元璋于1368年建立明朝，初都南京；永乐年间迁都北京，经营北方边防并开展郑和下西洋等对外活动。明代前中期中央集权持续加强，农业、手工业与商业发展，后期经历财政压力、边疆战争和政治纷争。1644年李自成军攻入北京，崇祯帝自缢，明朝中央政权覆亡；南方明室政权此后继续抵抗。
明亡后朱氏多支并立：通行主线弘光→隆武→永历；鲁监国、绍武为并行朝廷。1662年永历帝殉，南明终结。')
