VALUES ('qing', '{"periods":[{"name":"金","start":{"year":1616,"month":2,"confidence":"month"},"end":{"year":1636,"month":5,"day":14,"confidence":"day"}},{"name":"清","start":{"year":1636,"month":5,"day":15,"confidence":"day"},"end":{"year":1912,"month":2,"confidence":"month"}}]}', ARRAY['清','大清','金','后金'], '女真→满洲', 'cn', 'east_asia', 1616, 2, NULL, 'month', 1912, 2, NULL, 'month', 19393, 22945, 'ochre', NULL, NULL, '1616年2月努尔哈赤建后金，1636年改国号大清；1912年2月宣统退位。')
