INSERT INTO events (id, name, kind, time_mode, at_confidence, start_confidence, end_confidence, date_note, at_year, at_month, at_day, at_abs, start_year, start_month, start_day, start_abs, end_year, end_month, end_day, end_abs, summary, meaning, content) VALUES ('kublai-change-country-name-to-yuan', '忽必烈改国号为大元', 'politics', 'point', 'day', NULL, NULL, '至元八年十一月十五日（公历1271年12月18日）', 1271, 12, 18, 15263, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '忽必烈在蒙古帝国扩张和汗位争夺之后，依汉地王朝定号传统颁《建国号诏》，取《易经》“乾元”之义，定国号为“大元”。此举确立元朝的汉文国号；对南宋的战争仍在继续，直到1279年崖山之战后才完成统一。', NULL, NULL)
