INSERT INTO events (id, name, kind, time_mode, at_confidence, start_confidence, end_confidence, date_note, at_year, at_month, at_day, at_abs, start_year, start_month, start_day, start_abs, end_year, end_month, end_day, end_abs, summary, meaning, content) VALUES ('zhu-yuanzhang-change-country-name-to-ming', '朱元璋改国号为大明', 'politics', 'point', 'day', NULL, NULL, '吴二年正月初四（公历1368年1月23日）', 1368, 1, 23, 16416, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '元末群雄割据中，朱元璋先以吴为政权称号，以应天为根据地。1368年正月初四，他在应天即皇帝位，定有天下之号为“大明”、年号洪武，吴政权由此转入明朝阶段；随后明军北伐攻取大都，元廷退居漠北。', NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, at_confidence = EXCLUDED.at_confidence, start_confidence = EXCLUDED.start_confidence, end_confidence = EXCLUDED.end_confidence, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_day = EXCLUDED.at_day, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary, meaning = EXCLUDED.meaning, content = EXCLUDED.content;
INSERT INTO events (id, name, kind, time_mode, at_confidence, start_confidence, end_confidence, date_note, at_year, at_month, at_day, at_abs, start_year, start_month, start_day, start_abs, end_year, end_month, end_day, end_abs, summary, meaning, content) VALUES ('huang-taiji-change-country-name-to-qing', '皇太极改国号为大清', 'politics', 'point', 'day', NULL, NULL, '天聪十年四月十一日（公历1636年5月15日）', 1636, 5, 15, 19636, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '努尔哈赤建立的后金政权由皇太极继承并扩张。天聪十年，皇太极在盛京称帝，改国号为“大清”、改元崇德，后金由此进入清朝阶段；此后清与明、朝鲜及蒙古诸部的战争和外交继续交织。', NULL, NULL)
